"use client";

/**
 * Rich diff rendering for tool-call rows, backed by @pierre/diffs
 * (https://github.com/pierrecomputer/pierre). Pairs with the tool-summary
 * module: feed a file item's `path`/`oldText`/`newText`/`fragment` straight
 * in and every product renders the same syntax-highlighted, theme-aware diff.
 *
 * @pierre/diffs is an optional peer dependency — only consumers importing
 * this subpath need to install it.
 */

import { parseDiffFromFile } from "@pierre/diffs";
import { FileDiff, type FileDiffProps } from "@pierre/diffs/react";
import { type CSSProperties, useMemo } from "react";

type DiffOptions = NonNullable<FileDiffProps<undefined>["options"]>;

export type ToolFileDiffProps = {
	/** File path; used for the header-less language inference. */
	path: string;
	/** Contents after the change. */
	newText: string;
	/** Contents before the change; omit for created files. */
	oldText?: string;
	/**
	 * Set when oldText/newText are fragments of the file (editor str_replace
	 * payloads, apply_patch update sections) rather than complete contents.
	 * Fragments hide line numbers, which would otherwise misleadingly start
	 * at 1.
	 */
	fragment?: boolean;
	className?: string;
	/**
	 * CSS color (or var()) the diff surface uses as its base background; all
	 * of @pierre/diffs' derived tints (context lines, gutters, separators)
	 * are color-mixed from it. Defaults to the host app's `--background`
	 * token so diffs sit on the app surface instead of pierre's pure
	 * white/black theme background.
	 */
	background?: string;
	/** Merged over the defaults for per-product tuning. */
	options?: DiffOptions;
};

const BASE_OPTIONS: DiffOptions = {
	diffStyle: "unified",
	disableFileHeader: true,
	themeType: "system",
};

// Tool payloads carry code fragments that rarely end in a newline, which
// would otherwise litter every diff with "No newline at end of file"
// markers — meaningless noise for chat rows. Empty text stays empty so an
// empty side diffs as zero lines rather than one blank line.
function ensureTrailingNewline(text: string): string {
	if (!text) return "";
	return text.endsWith("\n") ? text : `${text}\n`;
}

export function ToolFileDiff({
	background = "var(--background, light-dark(#fff, #000))",
	className,
	fragment = false,
	newText,
	oldText,
	options,
	path,
}: ToolFileDiffProps) {
	const fileDiff = useMemo(() => {
		try {
			return parseDiffFromFile(
				oldText !== undefined
					? { contents: ensureTrailingNewline(oldText), name: path }
					: null,
				{ contents: ensureTrailingNewline(newText), name: path },
			);
		} catch {
			// Unparsable or identical contents — the row's +/- badge and
			// detail lines still describe the change.
			return null;
		}
	}, [oldText, newText, path]);
	const resolvedOptions = useMemo(
		() => ({
			...BASE_OPTIONS,
			...(fragment ? { disableLineNumbers: true } : {}),
			...options,
		}),
		[fragment, options],
	);

	if (!fileDiff) return null;
	return (
		<FileDiff
			className={className}
			fileDiff={fileDiff}
			options={resolvedOptions}
			style={
				{
					"--diffs-light-bg": background,
					"--diffs-dark-bg": background,
					// @pierre/diffs declares `color-scheme: light dark` on its
					// shadow :host, so its light-dark() token colors follow the
					// browser's preferred scheme — not the host app's
					// class-based theme — leaving e.g. near-black light-palette
					// text on a dark app surface. Inheriting the app's
					// color-scheme (flipped by `.dark` in the @cline/ui theme)
					// keeps the syntax palette in lockstep with the app theme.
					// Skipped when a caller pins an explicit themeType, which
					// pierre implements as its own :host color-scheme rule.
					...(resolvedOptions.themeType === "system" ||
					resolvedOptions.themeType === undefined
						? { colorScheme: "inherit" }
						: {}),
				} as CSSProperties
			}
		/>
	);
}

function computeLcs(a: string[], b: string[]): number[][] {
	const m = a.length;
	const n = b.length;
	const dp: number[][] = Array.from({ length: m + 1 }, () =>
		new Array(n + 1).fill(0),
	);
	for (let i = 1; i <= m; i++) {
		for (let j = 1; j <= n; j++) {
			dp[i][j] =
				a[i - 1] === b[j - 1]
					? dp[i - 1][j - 1] + 1
					: Math.max(dp[i - 1][j], dp[i][j - 1]);
		}
	}
	return dp;
}

function diffLines(
	oldLines: string[],
	newLines: string[],
): { type: "+" | "-" | " "; line: string }[] {
	const dp = computeLcs(oldLines, newLines);
	const result: { type: "+" | "-" | " "; line: string }[] = [];
	let i = oldLines.length;
	let j = newLines.length;
	while (i > 0 || j > 0) {
		if (i > 0 && j > 0 && oldLines[i - 1] === newLines[j - 1]) {
			result.unshift({ type: " ", line: oldLines[i - 1] });
			i--;
			j--;
		} else if (j > 0 && (i === 0 || dp[i][j - 1] >= dp[i - 1][j])) {
			result.unshift({ type: "+", line: newLines[j - 1] });
			j--;
		} else {
			result.unshift({ type: "-", line: oldLines[i - 1] });
			i--;
		}
	}
	return result;
}

/** Honest hunk separator for diffs built from file fragments. */
export const FRAGMENT_HUNK_HEADER = "@@ … @@";

export type MakeUnifiedDiffOptions = {
	/**
	 * Set when oldText/newText are fragments of a larger file (e.g. editor
	 * str_replace payloads) rather than complete file contents. Hunk headers
	 * then render as `@@ … @@` instead of fabricating line-1-relative
	 * positions that would mislocate the change.
	 */
	fragment?: boolean;
};

export function makeUnifiedDiff(
	oldText: string,
	newText: string,
	filePath: string,
	ctx = 3,
	options?: MakeUnifiedDiffOptions,
): string {
	// Empty text means zero lines, not one blank line — otherwise creating an
	// empty file or deleting all content reports a phantom blank addition.
	const oldArr = oldText ? oldText.split("\n") : [];
	const newArr = newText ? newText.split("\n") : [];
	const ops = diffLines(oldArr, newArr);

	const output: string[] = [];
	output.push(`--- a/${filePath}`);
	output.push(`+++ b/${filePath}`);

	let i = 0;
	while (i < ops.length) {
		if (ops[i].type === " ") {
			i++;
			continue;
		}

		const hunkStart = Math.max(0, i - ctx);
		let end = i;
		while (end < ops.length) {
			if (ops[end].type !== " ") {
				end++;
				continue;
			}
			let next = end;
			while (next < ops.length && ops[next].type === " ") next++;
			if (next < ops.length && next - end <= ctx * 2) {
				end = next + 1;
			} else {
				break;
			}
		}
		const hunkEnd = Math.min(ops.length, end + ctx);

		let oldCount = 0;
		let newCount = 0;
		for (let k = hunkStart; k < hunkEnd; k++) {
			if (ops[k].type !== "+") oldCount++;
			if (ops[k].type !== "-") newCount++;
		}

		let oldStart = 1;
		let newStart = 1;
		for (let k = 0; k < hunkStart; k++) {
			if (ops[k].type !== "+") oldStart++;
			if (ops[k].type !== "-") newStart++;
		}

		output.push(
			options?.fragment
				? FRAGMENT_HUNK_HEADER
				: `@@ -${oldStart},${oldCount} +${newStart},${newCount} @@`,
		);
		for (let k = hunkStart; k < hunkEnd; k++) {
			const prefix = ops[k].type === " " ? " " : ops[k].type;
			output.push(`${prefix}${ops[k].line}`);
		}

		i = hunkEnd;
	}

	return output.join("\n");
}

export function hunkHeader(lines: string[]): string {
	let oldCount = 0;
	let newCount = 0;
	for (const l of lines) {
		if (!l.startsWith("+")) oldCount++;
		if (!l.startsWith("-")) newCount++;
	}
	return `@@ -1,${oldCount} +1,${newCount} @@`;
}

/**
 * Count added/removed lines in a unified diff, ignoring the `---`/`+++`
 * file headers and `@@` hunk headers.
 */
export function countDiffLines(diff: string): {
	additions: number;
	deletions: number;
} {
	let additions = 0;
	let deletions = 0;
	for (const line of diff.split("\n")) {
		if (line.startsWith("+++") || line.startsWith("---")) continue;
		if (line.startsWith("+")) additions++;
		else if (line.startsWith("-")) deletions++;
	}
	return { additions, deletions };
}

/**
 * Shared, framework-free presentation logic for agent tool calls.
 *
 * Consumers (desktop app, cloud dashboard, future clients) feed the raw
 * `{ toolName, input, result }` payload of a tool call in and get back a
 * structured summary — label, per-item details, diff counts, extracted
 * output text — which they render with the agent-chat primitives
 * (`ToolActivityTrigger`, `ToolActivityDetails`, …) and their own icons.
 *
 * This module is pure data-in/data-out: no React, no DOM, no Node APIs, and
 * no dependency on runtime schemas. Inputs are `unknown` and parsing is
 * defensive; a malformed payload degrades to a generic label, never a throw.
 */

import { countDiffLines, makeUnifiedDiff } from "./diff.js";
import {
	extractOutputText,
	isRecord,
	normalizeValue,
	parseApplyPatchInput,
	parseAskQuestionInput,
	parseEditorInput,
	parseEditorResultDiffCounts,
	parseReadFilesInput,
	parseRunCommandsInput,
	parseSearchInput,
	parseSpawnAgentInput,
	parseWebFetchInput,
} from "./parsers.js";
import { detectLanguage, displayFileName, shortenPath } from "./paths.js";
import { pluralize, type ToolAggregate, teamSummary } from "./team.js";

export {
	countDiffLines,
	FRAGMENT_HUNK_HEADER,
	type MakeUnifiedDiffOptions,
	makeUnifiedDiff,
} from "./diff.js";
export {
	type ApplyPatchFile,
	type ApplyPatchInfo,
	type AskQuestionInfo,
	buildReadFilesKeys,
	type EditorInfo,
	extractOutputText,
	parseApplyPatchInput,
	parseAskQuestionInput,
	parseEditorInput,
	parseEditorResultDiffCounts,
	parseReadFilesInput,
	parseRunCommandsInput,
	parseSearchInput,
	parseSpawnAgentInput,
	parseWebFetchInput,
	type ReadFilesInfo,
	type RunCommandsInfo,
	type SearchInfo,
	type SpawnAgentInfo,
	type WebFetchInfo,
} from "./parsers.js";
export { detectLanguage, displayFileName, shortenPath } from "./paths.js";
export { type ToolAggregate, teamSummary } from "./team.js";

export type ToolSummaryPayload = {
	toolName: string;
	/** Structured input, or a JSON string of it (both are accepted). */
	input?: unknown;
	/** Raw tool result: string, content-block array, or record. */
	result?: unknown;
	isError?: boolean;
	inProgress?: boolean;
};

export type ToolKind =
	| "read"
	| "edit"
	| "command"
	| "search"
	| "web"
	| "spawn"
	| "team"
	| "skill"
	| "mcp"
	| "question"
	| "other";

export type ToolSummaryItem =
	| {
			type: "file";
			path: string;
			displayPath: string;
			startLine?: number;
			endLine?: number;
			language?: string;
			additions?: number;
			deletions?: number;
			/** Unified diff text for this file, when reconstructable. */
			diff?: string;
			/**
			 * Raw before/after texts for rich diff renderers (e.g.
			 * @pierre/diffs). `oldText` is absent for created files.
			 */
			oldText?: string;
			newText?: string;
			/**
			 * True when oldText/newText are fragments of the file rather than
			 * complete contents — renderers should hide absolute line numbers.
			 */
			fragment?: boolean;
			/**
			 * Per-hunk before/after texts when the change has more than one
			 * hunk (apply_patch). Render one diff per hunk — re-diffing
			 * concatenated hunks pairs deletions with unrelated additions.
			 * When present, prefer it over oldText/newText.
			 */
			hunks?: Array<{ oldText: string; newText: string }>;
	  }
	| { type: "command"; command: string }
	| { type: "query"; query: string }
	| { type: "url"; url: string }
	| { type: "text"; text: string };

/**
 * One styled segment of a row label. Segments with `code: true` carry code
 * (file names, commands, queries, URLs) and should render in a monospace
 * face; plain segments are prose.
 */
export type ToolLabelPart = { text: string; code?: boolean };

export type ToolSummary = {
	/** Normalized tool name (aliases applied). */
	toolName: string;
	kind: ToolKind;
	/** Row label, e.g. `Read app.tsx (10–80)` or `$ bun test`. */
	label: string;
	/** The label broken into styled segments; joins to `label`. */
	labelParts: ToolLabelPart[];
	/** Present when this call can merge into grouped-row counts. */
	aggregate?: ToolAggregate;
	/** Structured per-item detail for custom rendering. */
	items: ToolSummaryItem[];
	/** Preformatted one-per-line details for the expanded panel. */
	details: string[];
	/** Net line changes, for the trigger's +/- badge. */
	diff?: { additions: number; deletions: number };
	/** Human-readable text extracted from the result, when useful. */
	outputText?: string;
	/** Error text when the call failed. */
	errorText?: string;
};

export type ToolSummaryOptions = {
	/** How file paths render in labels/details. Default: "shortened". */
	pathStyle?: "shortened" | "basename" | "full";
	/** Cap on extracted output/error text. Default: 64 KiB. */
	maxOutputChars?: number;
	/**
	 * Optional cap on inline label text (commands, tasks, questions).
	 * Unlimited by default: labels carry the full text (whitespace collapsed
	 * to one line) and the consumer's layout ellipsizes at the container
	 * edge. Set a number only for width-constrained surfaces like TUIs.
	 */
	maxInlineChars?: number;
};

const DEFAULT_OPTIONS: Required<ToolSummaryOptions> = {
	pathStyle: "shortened",
	maxOutputChars: 64 * 1024,
	maxInlineChars: Number.POSITIVE_INFINITY,
};

export const TOOL_NAME_ALIASES: Record<string, string> = {
	"apply-patch": "apply_patch",
	bash: "run_commands",
	edit: "editor",
	edit_file: "editor",
	"file-read": "read_files",
	file_read: "read_files",
	read_file: "read_files",
	search: "search_codebase",
	"spawn-agent": "spawn_agent",
	spawn_agent_tool: "spawn_agent",
	"web-fetch": "fetch_web_content",
	web_fetch: "fetch_web_content",
};

export function normalizeToolName(toolName: string): string {
	const normalized = toolName.toLowerCase();
	return TOOL_NAME_ALIASES[normalized] ?? normalized;
}

export function classifyTool(toolName: string): ToolKind {
	const name = normalizeToolName(toolName);
	if (name === "read_files") return "read";
	if (name === "editor" || name === "apply_patch") return "edit";
	if (name === "run_commands") return "command";
	if (name === "search_codebase") return "search";
	if (name === "fetch_web_content") return "web";
	if (name === "spawn_agent" || name.startsWith("subagent_")) return "spawn";
	if (name === "team" || name === "teams" || name.startsWith("team_"))
		return "team";
	if (name === "skills" || name === "skill") return "skill";
	if (name === "ask_question" || name === "ask_followup_question")
		return "question";
	if (name === "mcp" || name.startsWith("mcp_") || name.startsWith("mcp-"))
		return "mcp";
	// Fuzzy fallbacks for runtimes with their own tool names.
	if (name.includes("command") || name.includes("terminal")) return "command";
	if (name.includes("read")) return "read";
	if (name.includes("edit") || name.includes("write")) return "edit";
	if (name.includes("search") || name.includes("grep")) return "search";
	if (
		name.includes("browser") ||
		name.includes("fetch") ||
		name.includes("web")
	)
		return "web";
	if (name.includes("mcp")) return "mcp";
	return "other";
}

function truncate(text: string, maxLen: number): string {
	const collapsed = text.replace(/\s+/g, " ").trim();
	if (collapsed.length <= maxLen) return collapsed;
	return `${collapsed.slice(0, Math.max(1, maxLen - 1)).trimEnd()}…`;
}

function humanizeToolName(toolName: string): string {
	const cleaned = toolName
		.replace(/^mcp[-_]+/i, "")
		.replace(/[-_]+/g, " ")
		.trim();
	if (!cleaned) return toolName;
	return cleaned.charAt(0).toUpperCase() + cleaned.slice(1);
}

function formatPath(
	path: string,
	style: Required<ToolSummaryOptions>["pathStyle"],
): string {
	if (style === "basename") return displayFileName(path);
	if (style === "full") return path;
	return shortenPath(path);
}

/** ` (10–80)` / ` (10+)` label suffix for a partial-file read. */
function lineRangeLabelSuffix(startLine?: number, endLine?: number): string {
	if (startLine !== undefined && endLine !== undefined)
		return ` (${startLine}–${endLine})`;
	if (startLine !== undefined) return ` (${startLine}+)`;
	if (endLine !== undefined) return ` (1–${endLine})`;
	return "";
}

/** `:10-80` detail suffix for a partial-file read. */
function lineRangeDetailSuffix(startLine?: number, endLine?: number): string {
	if (startLine !== undefined && endLine !== undefined)
		return `:${startLine}-${endLine}`;
	if (startLine !== undefined) return `:${startLine}+`;
	if (endLine !== undefined) return `:1-${endLine}`;
	return "";
}

function capText(
	text: string | undefined,
	maxChars: number,
): string | undefined {
	if (text === undefined) return undefined;
	if (text.length <= maxChars) return text;
	return `${text.slice(0, maxChars)}\n\n[output truncated]`;
}

function extractErrorText(
	result: unknown,
	maxChars: number,
): string | undefined {
	const normalized = normalizeValue(result);
	if (isRecord(normalized) && typeof normalized.error === "string") {
		return capText(normalized.error, maxChars);
	}
	return capText(extractOutputText(normalized), maxChars);
}

function fallbackLabel(kind: ToolKind, toolName: string, inProgress: boolean) {
	switch (kind) {
		case "read":
			return inProgress ? "Reading file" : "Read file";
		case "edit":
			return inProgress ? "Editing file" : "Edited file";
		case "command":
			return inProgress ? "Running command" : "Ran command";
		case "search":
			return inProgress ? "Searching" : "Searched";
		case "web":
			return inProgress ? "Fetching web content" : "Fetched web content";
		case "spawn":
			return inProgress ? "Spawning agent" : "Spawned agent";
		case "skill":
			return inProgress ? "Using skill" : "Used skill";
		case "question":
			return inProgress ? "Asking a question" : "Asked a question";
		case "mcp":
			return inProgress ? "Calling MCP tool" : "Called MCP tool";
		default:
			return inProgress
				? `Running ${humanizeToolName(toolName)}`
				: humanizeToolName(toolName);
	}
}

const READ_AGGREGATE = {
	key: "read-files",
	noun: "file",
	completedVerb: "Read",
	progressVerb: "Reading",
} as const;
const EDIT_AGGREGATE = {
	key: "edited-files",
	noun: "file",
	completedVerb: "Edited",
	progressVerb: "Editing",
} as const;
const COMMAND_AGGREGATE = {
	key: "commands",
	noun: "command",
	completedVerb: "Ran",
	progressVerb: "Running",
} as const;
const SEARCH_AGGREGATE = {
	key: "searches",
	noun: "search",
	pluralNoun: "searches",
	completedVerb: "Explored",
	progressVerb: "Exploring",
} as const;
const WEB_AGGREGATE = {
	key: "links",
	noun: "link",
	completedVerb: "Explored",
	progressVerb: "Exploring",
} as const;
const SPAWN_AGGREGATE = {
	key: "spawned-agents",
	noun: "agent",
	completedVerb: "Spawned",
	progressVerb: "Spawning",
} as const;

function aggregateLabel(
	aggregate: Omit<ToolAggregate, "count">,
	count: number,
	inProgress: boolean,
): string {
	const verb = inProgress ? aggregate.progressVerb : aggregate.completedVerb;
	return `${verb} ${pluralize(count, aggregate.noun, aggregate.pluralNoun)}`;
}

/** Derive the plain-text label and its styled segments together. */
function labeled(
	parts: ToolLabelPart[],
): Pick<ToolSummary, "label" | "labelParts"> {
	return { label: parts.map((part) => part.text).join(""), labelParts: parts };
}

// Fallback summaries (unparsable or absent input) still carry an aggregate
// so consecutive calls merge into grouped counts ("Spawned 3 agents") rather
// than repeating the generic label.
const FALLBACK_AGGREGATES: Partial<
	Record<ToolKind, Omit<ToolAggregate, "count">>
> = {
	command: COMMAND_AGGREGATE,
	edit: EDIT_AGGREGATE,
	read: READ_AGGREGATE,
	search: SEARCH_AGGREGATE,
	spawn: SPAWN_AGGREGATE,
	web: WEB_AGGREGATE,
};

/**
 * Build the presentation summary for one tool call.
 *
 * Single-item calls carry their specifics inline in the label
 * (`Read app.tsx (10–80)`, `Ran bun test`, `Edited chat-view.tsx`); calls
 * over multiple items aggregate (`Read 3 files`) with per-item lines in
 * `details`. Never throws on malformed input.
 */
export function buildToolSummary(
	payload: ToolSummaryPayload,
	options?: ToolSummaryOptions,
): ToolSummary {
	const opts = { ...DEFAULT_OPTIONS, ...options };
	const toolName = normalizeToolName(payload.toolName || "tool");
	const kind = classifyTool(toolName);
	const inProgress = payload.inProgress ?? false;
	const isError = payload.isError ?? false;
	const input = normalizeValue(payload.input);
	const fallbackAggregate = FALLBACK_AGGREGATES[kind];
	const base: ToolSummary = {
		toolName,
		kind,
		...labeled([{ text: fallbackLabel(kind, toolName, inProgress) }]),
		aggregate: fallbackAggregate
			? { ...fallbackAggregate, count: 1 }
			: undefined,
		items: [],
		details: [],
	};
	if (isError) {
		base.errorText = extractErrorText(payload.result, opts.maxOutputChars);
	}

	if (kind === "team") {
		const team = teamSummary(
			toolName,
			input,
			payload.result,
			inProgress,
			isError,
		);
		if (team) {
			return {
				...base,
				...labeled([{ text: team.label }]),
				aggregate: team.aggregate,
				details: team.details,
				items: team.details.map((text) => ({ type: "text", text })),
			};
		}
	}

	if (toolName === "read_files") {
		const info = parseReadFilesInput(input);
		if (info) {
			const items: ToolSummaryItem[] = info.files.map((file) => ({
				type: "file",
				path: file.path,
				displayPath: formatPath(file.path, opts.pathStyle),
				startLine: file.startLine,
				endLine: file.endLine,
				language: detectLanguage(file.path),
			}));
			const single = info.files.length === 1 ? info.files[0] : null;
			return {
				...base,
				...labeled(
					single
						? [
								{ text: `${inProgress ? "Reading" : "Read"} file ` },
								{
									text: `${displayFileName(single.path)}${lineRangeLabelSuffix(single.startLine, single.endLine)}`,
									code: true,
								},
							]
						: [
								{
									text: aggregateLabel(
										READ_AGGREGATE,
										info.files.length,
										inProgress,
									),
								},
							],
				),
				aggregate: { ...READ_AGGREGATE, count: info.files.length },
				items,
				details: info.files.map(
					(file) =>
						`${formatPath(file.path, opts.pathStyle)}${lineRangeDetailSuffix(file.startLine, file.endLine)}`,
				),
			};
		}
	}

	if (toolName === "run_commands") {
		const info = parseRunCommandsInput(input);
		if (info) {
			const commands = info.commands.map((command) => command.trim());
			const singleInline =
				commands.length === 1
					? truncate(commands[0], opts.maxInlineChars)
					: null;
			return {
				...base,
				// Single commands lead with the action, command in mono after.
				...labeled(
					singleInline !== null
						? [
								{ text: `${inProgress ? "Running" : "Ran"} command ` },
								{ text: singleInline, code: true },
							]
						: [
								{
									text: aggregateLabel(
										COMMAND_AGGREGATE,
										commands.length,
										inProgress,
									),
								},
							],
				),
				aggregate: { ...COMMAND_AGGREGATE, count: commands.length },
				items: commands.map((command) => ({ type: "command", command })),
				// The label may be ellipsized by the consumer's layout, so the
				// expanded panel always carries the full command text.
				details: commands,
				outputText: isError
					? undefined
					: capText(extractOutputText(payload.result), opts.maxOutputChars),
			};
		}
	}

	if (toolName === "search_codebase") {
		const info = parseSearchInput(input);
		if (info) {
			return {
				...base,
				...labeled(
					info.queries.length === 1
						? [
								{ text: `${inProgress ? "Searching" : "Searched"} ` },
								{
									text: truncate(info.queries[0], opts.maxInlineChars),
									code: true,
								},
							]
						: [
								{
									text: aggregateLabel(
										SEARCH_AGGREGATE,
										info.queries.length,
										inProgress,
									),
								},
							],
				),
				aggregate: { ...SEARCH_AGGREGATE, count: info.queries.length },
				items: info.queries.map((query) => ({ type: "query", query })),
				details: info.queries,
			};
		}
	}

	if (toolName === "fetch_web_content") {
		const info = parseWebFetchInput(input);
		if (info) {
			return {
				...base,
				...labeled(
					info.urls.length === 1
						? [
								{ text: `${inProgress ? "Fetching" : "Fetched"} ` },
								{
									text: truncate(info.urls[0], opts.maxInlineChars),
									code: true,
								},
							]
						: [
								{
									text: aggregateLabel(
										WEB_AGGREGATE,
										info.urls.length,
										inProgress,
									),
								},
							],
				),
				aggregate: { ...WEB_AGGREGATE, count: info.urls.length },
				items: info.urls.map((url) => ({ type: "url", url })),
				details: info.urls,
			};
		}
	}

	if (toolName === "apply_patch") {
		const info = parseApplyPatchInput(input);
		if (info) {
			const single = info.files.length === 1 ? info.files[0] : null;
			const actionVerb = (action: "add" | "update" | "delete") =>
				action === "add"
					? inProgress
						? "Creating file"
						: "Created file"
					: action === "delete"
						? inProgress
							? "Deleting file"
							: "Deleted file"
						: inProgress
							? "Editing file"
							: "Edited file";
			// Renames display as `old → new`.
			const fileLabel = (file: (typeof info.files)[number]) =>
				file.movedTo
					? `${displayFileName(file.path)} → ${displayFileName(file.movedTo)}`
					: displayFileName(file.path);
			const filePathDetail = (file: (typeof info.files)[number]) =>
				file.movedTo
					? `${formatPath(file.path, opts.pathStyle)} → ${formatPath(file.movedTo, opts.pathStyle)}`
					: formatPath(file.path, opts.pathStyle);
			return {
				...base,
				...labeled(
					single
						? [
								{ text: `${actionVerb(single.action)} ` },
								{ text: fileLabel(single), code: true },
							]
						: [
								{
									text: aggregateLabel(
										EDIT_AGGREGATE,
										info.files.length,
										inProgress,
									),
								},
							],
				),
				aggregate: { ...EDIT_AGGREGATE, count: info.files.length },
				diff: { additions: info.additions, deletions: info.deletions },
				items: info.files.map((file) => ({
					type: "file",
					path: file.movedTo ?? file.path,
					displayPath: formatPath(file.movedTo ?? file.path, opts.pathStyle),
					language: detectLanguage(file.movedTo ?? file.path),
					additions: file.additions,
					deletions: file.deletions,
					diff: file.diff,
					// Deletions have no meaningful rich diff; single-hunk changes
					// expose plain texts, multi-hunk changes must render per hunk.
					oldText:
						file.action !== "delete" && file.hunks.length === 1
							? file.action === "add"
								? undefined
								: file.hunks[0].oldText
							: undefined,
					newText:
						file.action !== "delete" && file.hunks.length === 1
							? file.hunks[0].newText
							: undefined,
					hunks:
						file.action !== "delete" && file.hunks.length > 1
							? file.hunks
							: undefined,
					fragment: file.action !== "add",
				})),
				details: info.files.map((file) =>
					file.action === "delete"
						? `Deleted ${filePathDetail(file)}`
						: `${filePathDetail(file)} +${file.additions} -${file.deletions}`,
				),
			};
		}
		return {
			...base,
			...labeled([{ text: inProgress ? "Applying patch" : "Applied patch" }]),
			aggregate: { ...EDIT_AGGREGATE, count: 1 },
		};
	}

	if (toolName === "editor") {
		const info = parseEditorInput(input);
		const inputRecord = isRecord(input) ? input : null;
		const path =
			info?.path ??
			(typeof inputRecord?.path === "string" ? inputRecord.path : undefined);
		// The editor schema has no `command`; derive the action from the shape.
		const command =
			typeof inputRecord?.command === "string"
				? inputRecord.command
				: inputRecord?.insert_line != null
					? "insert"
					: typeof inputRecord?.old_text === "string"
						? "str_replace"
						: typeof inputRecord?.new_text === "string"
							? "create"
							: "edit";
		const verb = inProgress
			? command === "create"
				? "Creating file"
				: command === "insert"
					? "Inserting into"
					: "Editing file"
			: command === "create"
				? "Created file"
				: command === "insert"
					? "Inserted into"
					: "Edited file";

		let diff: ToolSummary["diff"];
		let diffText: string | undefined;
		if (info && (info.oldText !== undefined || command === "create")) {
			// str_replace texts are fragments of the file, not whole contents;
			// fragment mode keeps the hunk header from claiming line positions.
			diffText = makeUnifiedDiff(
				info.oldText ?? "",
				info.newText,
				info.path,
				3,
				{
					fragment: command !== "create",
				},
			);
			diff = countDiffLines(diffText);
		} else {
			diff = parseEditorResultDiffCounts(payload.result) ?? undefined;
		}

		if (path) {
			return {
				...base,
				...labeled([
					{ text: `${verb} ` },
					{ text: displayFileName(path), code: true },
				]),
				aggregate: { ...EDIT_AGGREGATE, count: 1 },
				diff,
				items: [
					{
						type: "file",
						path,
						displayPath: formatPath(path, opts.pathStyle),
						language: detectLanguage(path),
						additions: diff?.additions,
						deletions: diff?.deletions,
						diff: diffText,
						oldText: info?.oldText,
						newText: info?.newText,
						fragment: command !== "create",
					},
				],
				// The label carries the basename; the expanded panel leads with
				// the fuller path above the diff, matching read rows.
				details: [formatPath(path, opts.pathStyle)],
			};
		}
	}

	if (toolName === "spawn_agent" || toolName.startsWith("subagent_")) {
		const info = parseSpawnAgentInput(input);
		if (info) {
			return {
				...base,
				...labeled([
					{ text: `${inProgress ? "Spawning" : "Spawned"} agent: ` },
					{ text: truncate(info.task, opts.maxInlineChars) },
				]),
				aggregate: { ...SPAWN_AGGREGATE, count: 1 },
				items: [{ type: "text", text: info.task }],
				details: [info.task],
			};
		}
	}

	if (kind === "skill") {
		const record = isRecord(input) ? input : null;
		const skill = typeof record?.skill === "string" ? record.skill : "";
		const args = typeof record?.args === "string" ? record.args : "";
		if (skill) {
			const detail = args ? `${skill} ${args}` : skill;
			return {
				...base,
				...labeled([
					{ text: `${inProgress ? "Using" : "Used"} skill ` },
					{ text: truncate(skill, opts.maxInlineChars), code: true },
				]),
				items: [{ type: "text", text: detail }],
				details: [detail],
			};
		}
	}

	if (kind === "question") {
		const info = parseAskQuestionInput(input);
		if (info) {
			return {
				...base,
				...labeled([
					{
						text: `${inProgress ? "Asking" : "Asked"} "${truncate(info.question, opts.maxInlineChars)}"`,
					},
				]),
				items: [
					{ type: "text", text: info.question },
					...info.options.map((option): ToolSummaryItem => {
						return { type: "text", text: option };
					}),
				],
				details: info.options,
				outputText: isError
					? undefined
					: capText(extractOutputText(payload.result), opts.maxOutputChars),
			};
		}
	}

	// Unknown/MCP tools: humanized name, plus whatever text the result holds.
	const normalizedResult = normalizeValue(payload.result);
	const resultRecord = isRecord(normalizedResult) ? normalizedResult : null;
	const query =
		typeof resultRecord?.query === "string" ? resultRecord.query : "";
	return {
		...base,
		...(query ? labeled([{ text: truncate(query, opts.maxInlineChars) }]) : {}),
		outputText: isError
			? undefined
			: capText(extractOutputText(normalizedResult), opts.maxOutputChars),
	};
}

/**
 * Merge the labels of consecutive tool calls into one grouped-row label.
 * Adjacent same-kind aggregates merge their counts ("Read 3 files"); other
 * labels pass through, joined with " · ".
 */
export function buildGroupedToolLabel(
	summaries: Array<{
		label: string;
		aggregate?: ToolAggregate;
		inProgress?: boolean;
	}>,
): string {
	if (summaries.length === 1) {
		return summaries[0]?.label ?? "Tool";
	}

	type Segment =
		| { type: "label"; label: string }
		| { type: "aggregate"; aggregate: ToolAggregate & { inProgress: boolean } };
	const segments: Segment[] = [];
	for (const summary of summaries) {
		const aggregate = summary.aggregate;
		if (!aggregate) {
			segments.push({ type: "label", label: summary.label });
			continue;
		}

		const previous = segments.at(-1);
		if (
			previous?.type === "aggregate" &&
			previous.aggregate.key === aggregate.key
		) {
			segments[segments.length - 1] = {
				type: "aggregate",
				aggregate: {
					...previous.aggregate,
					count: previous.aggregate.count + aggregate.count,
					inProgress:
						previous.aggregate.inProgress || (summary.inProgress ?? false),
				},
			};
			continue;
		}

		segments.push({
			type: "aggregate",
			aggregate: { ...aggregate, inProgress: summary.inProgress ?? false },
		});
	}

	return segments
		.map((segment) => {
			if (segment.type === "label") return segment.label;
			const { aggregate } = segment;
			const verb = aggregate.inProgress
				? aggregate.progressVerb
				: aggregate.completedVerb;
			return `${verb} ${pluralize(
				aggregate.count,
				aggregate.noun,
				aggregate.pluralNoun,
			)}`;
		})
		.join(" · ");
}

import { FRAGMENT_HUNK_HEADER, hunkHeader } from "./diff.js";

export function isRecord(value: unknown): value is Record<string, unknown> {
	return !!value && typeof value === "object" && !Array.isArray(value);
}

/**
 * Tool inputs and results sometimes arrive as JSON strings rather than
 * structured objects (archived transcripts, some transports). Re-parse
 * anything that looks like serialized JSON; leave other values untouched.
 */
export function normalizeValue(value: unknown): unknown {
	if (typeof value !== "string") return value;
	const trimmed = value.trim();
	if (
		(trimmed.startsWith("{") && trimmed.endsWith("}")) ||
		(trimmed.startsWith("[") && trimmed.endsWith("]"))
	) {
		try {
			return JSON.parse(trimmed) as unknown;
		} catch {
			return value;
		}
	}
	return value;
}

export interface ReadFilesInfo {
	files: { path: string; startLine?: number; endLine?: number }[];
}

/**
 * read_files accepts many input shapes across runtimes: `{ files: [{ path,
 * start_line, end_line }] }`, `{ files: "path" }`, `{ file_paths: [...] }`,
 * `{ paths: [...] }`, a bare array, or a bare string.
 */
export function parseReadFilesInput(input: unknown): ReadFilesInfo | undefined {
	const normalized = normalizeValue(input);
	const files: ReadFilesInfo["files"] = [];
	const push = (value: unknown) => {
		if (typeof value === "string" && value.length > 0) {
			files.push({ path: value });
			return;
		}
		if (isRecord(value) && typeof value.path === "string" && value.path) {
			files.push({
				path: value.path,
				startLine:
					typeof value.start_line === "number" ? value.start_line : undefined,
				endLine:
					typeof value.end_line === "number" ? value.end_line : undefined,
			});
		}
	};

	const record = isRecord(normalized) ? normalized : null;
	const candidates =
		record?.files ?? record?.file_paths ?? record?.paths ?? normalized;
	if (Array.isArray(candidates)) {
		for (const candidate of candidates) push(candidate);
	} else {
		push(candidates);
	}
	return files.length > 0 ? { files } : undefined;
}

// A read_files call can list the same path more than once, so the raw path is
// not a unique key. Prefix the array index to keep keys unique per row.
export function buildReadFilesKeys(files: { path: string }[]): string[] {
	return files.map((f, i) => `${i}:${f.path}`);
}

export interface RunCommandsInfo {
	commands: string[];
}

/**
 * run_commands accepts every shape in core's RunCommandsInputUnionSchema:
 * `{ commands: [...] }` (strings or `{ command, args }` entries, or a single
 * entry instead of an array), a bare array of either, a top-level
 * `{ command, args }`, `{ cmd }`, or a bare string.
 */
export function parseRunCommandsInput(
	input: unknown,
): RunCommandsInfo | undefined {
	const normalized = normalizeValue(input);
	const commands: string[] = [];
	const pushEntry = (entry: unknown) => {
		if (typeof entry === "string" && entry.length > 0) {
			commands.push(entry);
			return;
		}
		if (isRecord(entry) && typeof entry.command === "string" && entry.command) {
			const args = Array.isArray(entry.args)
				? entry.args.filter((a): a is string => typeof a === "string").join(" ")
				: "";
			commands.push(args ? `${entry.command} ${args}` : entry.command);
		}
	};

	if (typeof normalized === "string" || Array.isArray(normalized)) {
		for (const entry of Array.isArray(normalized) ? normalized : [normalized]) {
			pushEntry(entry);
		}
	} else if (isRecord(normalized)) {
		if (normalized.commands !== undefined) {
			const raw = normalized.commands;
			for (const entry of Array.isArray(raw) ? raw : [raw]) {
				pushEntry(entry);
			}
		} else if (typeof normalized.command === "string") {
			pushEntry(normalized);
		} else if (typeof normalized.cmd === "string") {
			pushEntry(normalized.cmd);
		}
	}
	return commands.length > 0 ? { commands } : undefined;
}

export interface EditorInfo {
	path: string;
	oldText?: string;
	newText: string;
	insertLine?: number;
}

export function parseEditorInput(input: unknown): EditorInfo | undefined {
	const normalized = normalizeValue(input);
	if (!isRecord(normalized)) return undefined;
	if (typeof normalized.path !== "string") return undefined;
	if (typeof normalized.new_text !== "string") return undefined;

	return {
		path: normalized.path,
		oldText:
			typeof normalized.old_text === "string" ? normalized.old_text : undefined,
		newText: normalized.new_text,
		insertLine:
			typeof normalized.insert_line === "number"
				? normalized.insert_line
				: undefined,
	};
}

export interface SearchInfo {
	queries: string[];
}

export function parseSearchInput(input: unknown): SearchInfo | undefined {
	const normalized = normalizeValue(input);
	if (!isRecord(normalized)) return undefined;
	if (!Array.isArray(normalized.queries)) return undefined;
	const queries = normalized.queries.filter(
		(q): q is string => typeof q === "string" && q.length > 0,
	);
	return queries.length > 0 ? { queries } : undefined;
}

export interface WebFetchInfo {
	urls: string[];
}

export function parseWebFetchInput(input: unknown): WebFetchInfo | undefined {
	const normalized = normalizeValue(input);
	if (!isRecord(normalized)) return undefined;
	if (!Array.isArray(normalized.requests)) return undefined;
	const urls = normalized.requests
		.filter((r): r is Record<string, unknown> => isRecord(r))
		.map((r) => (typeof r.url === "string" ? r.url : ""))
		.filter(Boolean);
	return urls.length > 0 ? { urls } : undefined;
}

export interface SpawnAgentInfo {
	task: string;
}

export function parseSpawnAgentInput(
	input: unknown,
): SpawnAgentInfo | undefined {
	const normalized = normalizeValue(input);
	if (!isRecord(normalized)) return undefined;
	if (typeof normalized.task !== "string") return undefined;
	return { task: normalized.task };
}

export interface AskQuestionInfo {
	question: string;
	options: string[];
}

export function parseAskQuestionInput(
	input: unknown,
): AskQuestionInfo | undefined {
	const normalized = normalizeValue(input);
	if (!isRecord(normalized)) return undefined;
	if (typeof normalized.question !== "string") return undefined;
	const options = Array.isArray(normalized.options)
		? normalized.options.filter((o): o is string => typeof o === "string")
		: [];
	return { question: normalized.question, options };
}

/** Before/after texts reconstructed from one `@@`-delimited patch section. */
export interface ApplyPatchHunk {
	oldText: string;
	newText: string;
}

export interface ApplyPatchFile {
	path: string;
	/** From the section header: `Add File`, `Update File`, or `Delete File`. */
	action: "add" | "update" | "delete";
	/** Destination path from a `*** Move to:` line, when the file was renamed. */
	movedTo?: string;
	additions: number;
	deletions: number;
	diff: string;
	/**
	 * Per-hunk before/after texts, boundaries preserved. Rendering each hunk
	 * separately matters: concatenating hunks and re-diffing would let a
	 * deletion in one hunk pair up with an addition in another.
	 */
	hunks: ApplyPatchHunk[];
}

export interface ApplyPatchInfo {
	files: ApplyPatchFile[];
	additions: number;
	deletions: number;
	diff: string;
}

const FILE_ACTION_RE = /^\*\*\* (Add|Update|Delete) File: (.+)/;
const MOVE_TO_RE = /^\*\*\* Move to: (.+)/;
// `@@ …` context markers delimit hunks and are handled separately below.
const HUNK_MARKER_RE = /^@@/;
const SKIP_LINES =
	/^(?:\*\*\* (?:Begin|End) Patch|%%bash|```|EOF|apply_patch\b|\*\*\* End of File)/;

/**
 * Parse the apply_patch envelope (`*** Add/Update/Delete File:` sections)
 * into per-file additions/deletions and a synthetic unified diff.
 */
export function parseApplyPatchInput(
	input: unknown,
): ApplyPatchInfo | undefined {
	const normalized = normalizeValue(input);
	const raw =
		typeof normalized === "string"
			? normalized
			: isRecord(normalized) && typeof normalized.input === "string"
				? normalized.input
				: null;
	if (!raw) return undefined;

	const files: ApplyPatchFile[] = [];
	let current: {
		path: string;
		action: "add" | "update" | "delete";
		movedTo?: string;
		lines: string[];
		hunk: string[];
		oldLines: string[];
		newLines: string[];
		hunks: ApplyPatchHunk[];
		additions: number;
		deletions: number;
	} | null = null;

	const flushHunk = () => {
		if (!current || current.hunk.length === 0) return;
		// Update/Delete sections are file fragments; only Add File sections
		// carry complete contents, so only they get real hunk positions.
		current.lines.push(
			current.action === "add"
				? hunkHeader(current.hunk)
				: FRAGMENT_HUNK_HEADER,
			...current.hunk,
		);
		current.hunks.push({
			oldText: current.oldLines.join("\n"),
			newText: current.newLines.join("\n"),
		});
		current.hunk = [];
		current.oldLines = [];
		current.newLines = [];
	};
	const flushFile = () => {
		if (!current) return;
		flushHunk();
		files.push({
			path: current.path,
			action: current.action,
			movedTo: current.movedTo,
			additions: current.additions,
			deletions: current.deletions,
			diff: current.lines.join("\n"),
			hunks: current.hunks,
		});
		current = null;
	};

	for (const line of raw.split("\n")) {
		const fileMatch = FILE_ACTION_RE.exec(line);
		if (fileMatch) {
			flushFile();
			const path = fileMatch[2].trim();
			current = {
				path,
				action: fileMatch[1].toLowerCase() as "add" | "update" | "delete",
				lines: [`--- a/${path}`, `+++ b/${path}`],
				hunk: [],
				oldLines: [],
				newLines: [],
				hunks: [],
				additions: 0,
				deletions: 0,
			};
			continue;
		}
		const moveMatch = MOVE_TO_RE.exec(line);
		if (moveMatch) {
			if (current) current.movedTo = moveMatch[1].trim();
			continue;
		}
		if (HUNK_MARKER_RE.test(line.trim())) {
			flushHunk();
			continue;
		}
		if (SKIP_LINES.test(line.trim())) continue;
		if (!current) continue;

		if (line.startsWith("+")) {
			current.additions++;
			current.newLines.push(line.slice(1));
		} else if (line.startsWith("-")) {
			current.deletions++;
			current.oldLines.push(line.slice(1));
		} else {
			const context = line.startsWith(" ") ? line.slice(1) : line;
			current.oldLines.push(context);
			current.newLines.push(context);
		}

		if (line.startsWith("+") || line.startsWith("-") || line.startsWith(" ")) {
			current.hunk.push(line);
		} else {
			current.hunk.push(` ${line}`);
		}
	}
	flushFile();

	if (files.length === 0) return undefined;
	return {
		files,
		additions: files.reduce((sum, f) => sum + f.additions, 0),
		deletions: files.reduce((sum, f) => sum + f.deletions, 0),
		diff: files.map((f) => f.diff).join("\n"),
	};
}

/**
 * The editor tool's result text encodes changed lines as `+12: …` / `-12: …`.
 * Used as a fallback when the input texts are unavailable for diffing.
 */
export function parseEditorResultDiffCounts(
	result: unknown,
): { additions: number; deletions: number } | null {
	const normalized = normalizeValue(result);
	const value = isRecord(normalized) ? normalized.result : normalized;
	if (typeof value !== "string") return null;
	let additions = 0;
	let deletions = 0;
	for (const line of value.split("\n")) {
		if (/^\+\d+:/.test(line)) additions += 1;
		if (/^-\d+:/.test(line)) deletions += 1;
	}
	if (additions === 0 && deletions === 0) return null;
	return { additions, deletions };
}

// Base64 payloads are one giant line; chunk to MIME width so line-based
// collapsed previews stay compact and expand shows the full data.
function chunkBase64(data: string): string {
	return data.match(/.{1,76}/g)?.join("\n") ?? data;
}

/**
 * Extract human-readable text from a tool result: plain strings,
 * `[{ result }]` arrays, and MCP `{ content: [...] }` shapes (text,
 * resource, resource_link, image/audio blocks) are all handled.
 */
export function extractOutputText(raw: unknown): string | undefined {
	if (raw === null || raw === undefined) return undefined;
	if (typeof raw === "string") return raw;

	if (Array.isArray(raw)) {
		const parts: string[] = [];
		for (const item of raw) {
			if (isRecord(item) && "result" in item) {
				const result = item.result;
				if (typeof result === "string") {
					parts.push(result);
				} else if (Array.isArray(result)) {
					for (const part of result) {
						if (
							isRecord(part) &&
							(part as { type?: string }).type === "text" &&
							"text" in part
						) {
							parts.push(String(part.text));
						}
					}
				}
			}
		}
		if (parts.length > 0) return parts.join("\n");
	}

	if (typeof raw === "object") {
		// MCP tools return {content: [{type: "text", text}, ...]}. Extract the
		// text so multi-line results keep real newlines instead of being
		// JSON-escaped into one giant line. Non-text blocks keep their
		// identifying metadata plus their base64 payloads so mixed results are
		// not silently truncated.
		const content = (raw as { content?: unknown }).content;
		if (Array.isArray(content)) {
			const parts = content
				.map((part) => {
					if (!isRecord(part)) return "";
					if (part.type === "text" && typeof part.text === "string") {
						return part.text;
					}
					if (part.type === "resource" && isRecord(part.resource)) {
						if (typeof part.resource.text === "string") {
							return part.resource.text;
						}
						if (typeof part.resource.blob === "string" && part.resource.blob) {
							const label =
								typeof part.resource.uri === "string"
									? `[resource: ${part.resource.uri}]`
									: "[resource]";
							return `${label}\n${chunkBase64(part.resource.blob)}`;
						}
						if (typeof part.resource.uri === "string") {
							return `[resource: ${part.resource.uri}]`;
						}
					}
					if (part.type === "resource_link" && typeof part.uri === "string") {
						return `[resource_link: ${part.uri}]`;
					}
					if (
						(part.type === "image" || part.type === "audio") &&
						typeof part.mimeType === "string"
					) {
						if (typeof part.data === "string" && part.data) {
							return `[${part.type}: ${part.mimeType}]\n${chunkBase64(part.data)}`;
						}
						return `[${part.type}: ${part.mimeType}]`;
					}
					return typeof part.type === "string" ? `[${part.type}]` : "";
				})
				.filter(Boolean);
			if (parts.length > 0) return parts.join("\n");
		}
		try {
			return JSON.stringify(raw, null, 2);
		} catch {
			return String(raw);
		}
	}

	return String(raw);
}

