async function run(command: string[], cwd: string): Promise<void> {
	const child = Bun.spawn(command, {
		cwd,
		stderr: "inherit",
		stdout: "inherit",
	});
	const exitCode = await child.exited;
	if (exitCode !== 0) {
		throw new Error(`${command.join(" ")} exited with ${exitCode}`);
	}
}

function createConsumer(root: string): void {
	mkdirSync(root, { recursive: true });
	writeFileSync(
		join(root, "package.json"),
		`${JSON.stringify({ name: "cline-ui-smoke", private: true, type: "module" }, null, 2)}\n`,
	);
}

async function compileTailwind(
	root: string,
	name: string,
	inputLines: string[],
	runner: string[],
): Promise<string> {
	const input = join(root, `${name}.css`);
	const output = join(root, `${name}-output.css`);
	writeFileSync(input, [...inputLines, ""].join("\n"));
	await run([...runner, "-i", input, "-o", output, "--minify"], root);
	return readFileSync(output, "utf8");
}

function expectCandidate(css: string, candidate: string): void {
	const selector = `.${candidate.replaceAll(":", "\\:").replaceAll("/", "\\/")}`;
	if (!css.includes(selector)) {
		throw new Error(`packed Tailwind source did not emit ${candidate}`);
	}
}

function expectFragment(css: string, fragment: string, contract: string): void {
	if (!css.includes(fragment)) {
		throw new Error(`${contract} did not emit ${fragment}`);
	}
}

async function verifyTailwindContract(
	root: string,
	runner: string[],
): Promise<void> {
	const css = await compileTailwind(
		root,
		"tailwind",
		[
			'@import "tailwindcss";',
			'@import "@cline/ui/theme/scoped-tokens.css";',
			'@import "@cline/ui/components.css";',
			"@theme inline {",
			"\t--color-background: var(--host-background);",
			"\t--radius-lg: var(--host-radius-lg);",
			"\t--text-sm--letter-spacing: var(--host-letter-spacing);",
			"}",
			'@source inline("bg-background rounded-lg text-sm");',
		],
		runner,
	);
	for (const candidate of [
		"bg-cline-ui-background/95",
		"border-cline-ui-border/60",
		"text-cline-ui-muted-foreground",
		"bg-cline-ui-primary/10",
		"max-h-56",
		"leading-none",
		"max-h-44",
		"not-last:border-b",
		"focus-visible:outline-3",
		"min-h-8",
		"resize-none",
	]) {
		expectCandidate(css, candidate);
	}
	for (const fragment of [
		"background-color:var(--host-background)",
		"border-radius:var(--host-radius-lg)",
		"letter-spacing:var(--host-letter-spacing)",
	]) {
		expectFragment(css, fragment, "host Tailwind namespace");
	}

	const noPreflightCss = await compileTailwind(
		root,
		"tailwind-no-preflight",
		[
			"@layer theme, base, components, utilities;",
			'@import "tailwindcss/theme.css" layer(theme);',
			'@import "@cline/ui/theme/scoped-tokens.css";',
			'@import "@cline/ui/components.css";',
			'@import "tailwindcss/utilities.css" layer(utilities);',
		],
		runner,
	);
	for (const fragment of [
		"box-sizing:border-box",
		"border-style:solid",
		"font-family:inherit",
		"margin:.5rem 0 0",
		"padding-block:0",
	]) {
		expectFragment(noPreflightCss, fragment, "no-Preflight Tailwind contract");
	}
}

const temporaryRoot = mkdtempSync(join(tmpdir(), "cline-ui-package-"));

try {
	let archive = process.argv[2] ? resolve(process.argv[2]) : undefined;
	if (!archive) {
		const packDirectory = join(temporaryRoot, "pack");
		mkdirSync(packDirectory, { recursive: true });
		await run(
			[
				process.execPath,
				"pm",
				"pack",
				"--ignore-scripts",
				"--destination",
				packDirectory,
			],
			packageRoot,
		);
		const archiveName = readdirSync(packDirectory).find((name) =>
			name.endsWith(".tgz"),
		);
		if (!archiveName) throw new Error("bun pm pack did not create an archive");
		archive = join(packDirectory, archiveName);
	}

	const bunConsumer = join(temporaryRoot, "bun-consumer");
	createConsumer(bunConsumer);
	await run(
		[
			process.execPath,
			"add",
			"--ignore-scripts",
			archive,
			"react@19.2.4",
			"react-dom@19.2.4",
			"@pierre/diffs@1.3.2",
			"tailwindcss@4.2.0",
			"@tailwindcss/cli@4.2.0",
		],
		bunConsumer,
	);
	await run([process.execPath, "-e", importCheck], bunConsumer);
	await verifyTailwindContract(bunConsumer, [
		process.execPath,
		"x",
		"tailwindcss",
	]);

	const npmConsumer = join(temporaryRoot, "npm-consumer");
	createConsumer(npmConsumer);
	await run(
		[
			"npm",
			"install",
			"--ignore-scripts",
			"--no-audit",
			"--no-fund",
			archive,
			"react@18.3.1",
			"react-dom@18.3.1",
			"@pierre/diffs@1.3.2",
			"tailwindcss@4.2.0",
			"@tailwindcss/cli@4.2.0",
		],
		npmConsumer,
	);
	await run(["node", "--input-type=module", "-e", importCheck], npmConsumer);
	await verifyTailwindContract(npmConsumer, [
		"npx",
		"--no-install",
		"tailwindcss",
	]);
	console.log(
		`Verified packed ${basename(archive)} with Bun/React 19 and npm/Node/React 18, including Tailwind contracts`,
	);
} finally {
	rmSync(temporaryRoot, { force: true, recursive: true });
}

import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";

const packageRoot = join(import.meta.dir, "..");
const readThemeFile = (name: string) =>
	readFileSync(join(packageRoot, "theme", name), "utf8");

const palette = readThemeFile("palette.css");
const tokens = readThemeFile("tokens.css");
const tokensWithoutComments = tokens.replace(/\/\*[\s\S]*?\*\//g, "");
const paletteWithoutComments = palette.replace(/\/\*[\s\S]*?\*\//g, "");
const scopedTokens = readThemeFile("scoped-tokens.css");
const theme = readThemeFile("theme.css");
const componentTheme = readThemeFile("component-theme.css");
const base = readThemeFile("base.css");
const index = readThemeFile("index.css");
const components = readFileSync(join(packageRoot, "components.css"), "utf8");
const manifest = JSON.parse(
	readFileSync(join(packageRoot, "package.json"), "utf8"),
) as { exports?: Record<string, string> };

const requiredTokens = [
	"--background",
	"--foreground",
	"--primary",
	"--border",
	"--font-sans",
	"--font-mono",
	"--font-weight-normal",
	"--text-xs",
	"--text-6xl",
	"--sidebar",
	"--surface-1",
	"--text-1",
	"--border-1",
	"--success-surface",
	"--warning-surface",
	"--error-surface",
	"--info-surface",
];

for (const token of requiredTokens) {
	if (!tokens.includes(`${token}:`)) {
		throw new Error(`tokens.css is missing ${token}`);
	}
}

for (const paletteName of [
	"neutral",
	"accent",
	"error",
	"success",
	"warning",
	"info",
]) {
	for (let step = 1; step <= 12; step += 1) {
		for (const token of [
			`--${paletteName}-${step}:`,
			`--${paletteName}-a${step}:`,
		]) {
			if (palette.split(token).length !== 3) {
				throw new Error(`palette.css must define ${token} once per mode`);
			}
		}
	}
}

if (
	palette.includes("--cline-") ||
	tokens.includes("--cline-") ||
	theme.includes("--cline-") ||
	base.includes("--cline-")
) {
	throw new Error("theme contract must not expose --cline-* variables");
}
if (
	/@(?:apply|custom-variant|layer|theme|supports|media)\b/.test(
		paletteWithoutComments + tokensWithoutComments,
	)
) {
	throw new Error("palette.css and tokens.css must remain framework-neutral");
}
if (!tokensWithoutComments.includes('@import "@cline/ui/theme/palette.css";')) {
	throw new Error("tokens.css must import the owned palette");
}
if (
	/--(?:slate|violet|ruby|green|amber|sky)-(?:a)?\d+:/.test(palette) ||
	/@import/.test(scopedTokens) ||
	/(^|\n):root\s*\{/.test(scopedTokens)
) {
	throw new Error("owned palette names and scoped theme isolation must hold");
}
if (theme.includes("tokens.css") || !theme.includes("@theme inline")) {
	throw new Error(
		"theme.css must contain only the Tailwind mapping and variants",
	);
}
if (
	!componentTheme.includes("Generated by scripts/generate-theme.ts") ||
	!componentTheme.includes("@custom-variant cline-ui-dark") ||
	!componentTheme.includes("@theme inline") ||
	componentTheme.includes("@custom-variant dark ")
) {
	throw new Error(
		"component-theme.css must contain the generated namespaced Tailwind contract",
	);
}
if (!components.includes('@import "./theme/component-theme.css";')) {
	throw new Error("components.css must import the namespaced component theme");
}
if (base.includes("#__next") || base.includes("@source")) {
	throw new Error("base.css must not contain consumer-specific shell policy");
}
if (
	!index.includes('@import "@cline/ui/theme/tokens.css";') ||
	!index.includes('@import "@cline/ui/theme/theme.css";') ||
	!index.includes('@import "@cline/ui/theme/base.css";')
) {
	throw new Error("theme entry point must compose tokens, theme, and base CSS");
}
for (const subpath of [
	"./components.css",
	"./components/markdown.css",
	"./theme/index.css",
	"./theme/palette.css",
	"./theme/scoped-tokens.css",
	"./theme/tokens.css",
	"./theme/theme.css",
	"./theme/base.css",
]) {
	const target = manifest.exports?.[subpath];
	if (!target || !existsSync(join(packageRoot, target))) {
		throw new Error(`package.json export ${subpath} is missing or invalid`);
	}
}

console.log("@cline/ui theme contract is valid");

