.dark {
	--brand-violet: oklch(0.7 0.17 293);
	--brand-violet-surface: oklch(0.48 0.18 293);
	--brand-violet-surface-foreground: oklch(0.97 0.01 293);
	--brand-lilac: oklch(0.68 0.13 315);
	--brand-magenta: oklch(0.64 0.17 330);
	--brand-periwinkle: oklch(0.63 0.16 275);
	--brand-cyan: oklch(0.72 0.09 210);
	--card-surface: var(--neutral-3);
	--font-weight-normal: 400;
	--font-weight-medium: 500;
	--font-weight-semibold: 600;
	--font-weight-bold: 600;
}

:root,
.dark {
	/* Readable visual roles. */
	--surface-1: var(--neutral-1);
	--surface-2: var(--neutral-2);
	--surface-3: var(--neutral-3);
	--surface-hover-lighter: var(--neutral-a2);
	--surface-hover-darker: var(--neutral-a3);
	--surface-hover: var(--surface-hover-darker);
	--text-1: var(--neutral-12);
	--text-2: var(--neutral-11);
	--text-disabled: var(--neutral-9);
	--border-1: var(--neutral-4);
	--border-2: var(--neutral-5);
	--focus-ring: var(--accent-8);

	/* Status roles. Alpha surfaces stay composable over any host surface. */
	--success-surface: var(--success-a3);
	--success-border: var(--success-a7);
	--success-solid: var(--success-9);
	--success-text: var(--success-11);
	--success-contrast: #fff;
	--warning-surface: var(--warning-a3);
	--warning-border: var(--warning-a7);
	--warning-solid: var(--warning-9);
	--warning-text: var(--warning-11);
	--warning-contrast: #1c2024;
	--error-surface: var(--error-a3);
	--error-border: var(--error-a7);
	--error-solid: var(--error-9);
	--error-text: var(--error-11);
	--error-contrast: #fff;
	--info-surface: var(--info-a3);
	--info-border: var(--info-a7);
	--info-solid: var(--info-9);
	--info-text: var(--info-11);
	--info-contrast: #1c2024;

	/* Global browser affordances. */
	--scrollbar-thumb: var(--neutral-8);
	--scrollbar-thumb-hover: var(--neutral-9);
	--selection-background: var(--accent-a5);

	/* Standard shadcn semantic surfaces. */
	--background: var(--surface-1);
	--foreground: var(--text-1);
	--card: var(--surface-2);
	--card-foreground: var(--text-1);
	--popover: var(--surface-2);
	--popover-foreground: var(--text-1);
	--primary: var(--accent-9);
	--primary-foreground: #fff;
	--primary-emphasis: var(--accent-10);
	--secondary: var(--surface-3);
	--secondary-foreground: var(--text-1);
	--muted: var(--surface-3);
	--muted-foreground: var(--text-2);
	--accent: var(--accent-3);
	--accent-foreground: var(--accent-11);
	--destructive: var(--error-solid);
	--destructive-foreground: var(--error-contrast);
	--border: var(--border-1);
	--input: var(--border-2);
	--ring: var(--focus-ring);
	--chart-1: var(--accent-9);
	--chart-2: var(--success-9);
	--chart-3: var(--info-9);
	--chart-4: var(--warning-9);
	--chart-5: var(--error-9);
	--radius: 0.5rem;
	--radius-sm: calc(var(--radius) - 4px);
	--radius-md: calc(var(--radius) - 2px);
	--radius-lg: var(--radius);
	--radius-xl: calc(var(--radius) + 4px);
	--sidebar: var(--surface-2);
	--sidebar-foreground: var(--text-1);
	--sidebar-primary: var(--accent-9);
	--sidebar-primary-foreground: #fff;
	--sidebar-accent: var(--accent-3);
	--sidebar-accent-foreground: var(--accent-11);
	--sidebar-border: var(--border-1);
	--sidebar-ring: var(--focus-ring);
}

